<?php
declare(strict_types=1);
require_once __DIR__.'/includes/ui.php';require_once __DIR__.'/includes/catalog_ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];
$q=mb_substr_available(trim((string)($_GET['q']??'')),80);$variant=in_array($_GET['variant']??'',['normal','paradox'],true)?$_GET['variant']:'';$page=max(1,(int)($_GET['page']??1));$where=' WHERE d.owner_id=?';$params=[$uid];
if($q!==''){$where.=' AND (s.name LIKE ? OR d.nickname LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}
if($variant!=='')$where.=$variant==='paradox'?" AND s.slug LIKE 'paradox-%'":" AND s.slug NOT LIKE 'paradox-%'";
$from=' FROM digimon_instances d JOIN digimon_species s ON s.id=d.species_id LEFT JOIN digimon_party p ON p.owner_id=d.owner_id AND p.digimon_id=d.id';$total=(int)dn_row($db,'SELECT COUNT(*) n'.$from.$where,$params)['n'];$pages=max(1,(int)ceil($total/24));$page=min($page,$pages);
$rows=dn_rows($db,'SELECT d.*,s.slug,s.name,s.stage,s.attribute,s.type,s.element,s.sprite,p.slot'.$from.$where.' ORDER BY COALESCE(p.slot,99),d.level DESC,d.id LIMIT 24 OFFSET ?',array_merge($params,[($page-1)*24]));$pager=['q'=>$q,'stage'=>'','variant'=>$variant,'ready'=>false,'total'=>$total,'page'=>$page,'pages'=>$pages];pv_page_start('Your Digimon','digimon.php',true);
?>
<div class="pv-game-layout"><?php pv_game_side_menu('digimon.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">PARTNER ARCHIVE / YOUR COLLECTION</span><h1>Your Digimon</h1><p class="pv-subtle">Find your partners, check their vitals and ABI, and open their training and evolution routes.</p></div><a class="pv-button" href="<?=pv_h(pv_url('materialize.php'))?>">Materialize Digimon</a></div>
<form method="get" class="dn-catalog-tools"><input type="search" name="q" aria-label="Search your Digimon" value="<?=pv_h($q)?>" placeholder="Name or nickname"><select name="variant" aria-label="Variant"><option value="">All variants</option><option value="normal" <?=$variant==='normal'?'selected':''?>>Standard</option><option value="paradox" <?=$variant==='paradox'?'selected':''?>>Paradox</option></select><button class="pv-button pv-button-secondary">Search collection</button></form>
<?php dn_catalog_pager($pager,'digimon.php');if($rows):?><div class="dn-digimon-grid"><?php foreach($rows as $d):?><div><?=dn_digimon_card($d)?><div class="dn-instance-actions"><a href="<?=pv_h(pv_url('digivolution.php?id='.(int)$d['id']))?>">Moves, training & evolution →</a></div></div><?php endforeach;?></div><?php else:?><div class="pv-empty">No Digimon match this search.</div><?php endif;dn_catalog_pager($pager,'digimon.php');?></section></main></div><?php pv_page_end();?>
